import Default from "@astrojs/starlight/components/PageTitle.astro";
---

<div class="tfsl-page-title-frame" data-tfsl-template="page-title-frame">
  <Default {...Astro.props} />
</div>

<style>
  .tfsl-page-title-frame {
    border-left: 4px solid var(--sl-color-accent);
    padding-left: 1rem;
    margin-bottom: 1.5rem;
  }
</style>

function deepCloneSafe(val) {
  if (Array.isArray(val)) return val.map(deepCloneSafe);
  if (val === null || typeof val !== "object") return val;
  const result = {};
  for (const key of Object.keys(val)) {
    if (["__proto__", "prototype", "constructor"].includes(key)) continue;
    Object.defineProperty(result, key, { value: deepCloneSafe(val[key]), enumerable: true, writable: true, configurable: true });
  }
  return result;
}
function mergeCodeConfig(defaults, consumer) {
  if (consumer === false) return false;
  if (consumer === undefined || consumer === true) return deepCloneSafe(defaults);
  if (consumer === null || typeof consumer !== "object" || Array.isArray(consumer)) return consumer;
  const proto = Object.getPrototypeOf(consumer);
  if (proto !== Object.prototype && proto !== null) return consumer;
  if (defaults === null || typeof defaults !== "object" || Array.isArray(defaults)) return consumer;
  const result = deepCloneSafe(defaults);
  for (const key of Reflect.ownKeys(consumer)) {
    if (typeof key === "string" && ["__proto__", "prototype", "constructor"].includes(key)) continue;
    const descriptor = Object.getOwnPropertyDescriptor(consumer, key);
    if (!descriptor) continue;
    if (!("value" in descriptor)) { Object.defineProperty(result, key, descriptor); continue; }
    const value = descriptor.value;
    if (value === undefined) continue;
    const themeValue = Object.hasOwn(defaults, key) ? defaults[key] : undefined;
    const branch = themeValue !== null && typeof themeValue === "object" && !Array.isArray(themeValue);
    const merged = branch && value !== true ? mergeCodeConfig(themeValue, value) : value;
    Object.defineProperty(result, key, { ...descriptor, value: merged });
  }
  return result;
}

export default function themePlugin() {
  return { name: "loom-black-code-baseline", hooks: {
    "config:setup"({ config, updateConfig }) {
      const defaults = ["loom-black-code-baseline/styles/layers.css","loom-black-code-baseline/styles/tokens.css","loom-black-code-baseline/styles/base.css","loom-black-code-baseline/styles/accent.css","loom-black-code-baseline/styles/overrides.css","loom-black-code-baseline/styles/code.css"];
      const customCss = [...defaults, ...(Array.isArray(config?.customCss) ? config.customCss : []).filter(path => !defaults.includes(path))];
      const components = { PageTitle: "loom-black-code-baseline/components/PageTitleFrame.astro", ...(config?.components ?? {}) };
      const ecDefaults = {"themes":[{"name":"loom-black-code-dark","type":"dark","bg":"#090a0d","fg":"#f0f2f5","tokenColors":[{"scope":["keyword"],"settings":{"foreground":"#eda2cf"}},{"scope":["string"],"settings":{"foreground":"#8bd0e8"}},{"scope":["comment"],"settings":{"foreground":"#a4b9ac"}},{"scope":["entity.name.function"],"settings":{"foreground":"#efb18a"}},{"scope":["variable"],"settings":{"foreground":"#bdb1eb"}},{"scope":["constant"],"settings":{"foreground":"#d5d28b"}}]},{"name":"loom-black-code-light","type":"light","bg":"#f1f5f9","fg":"#0f172a","tokenColors":[{"scope":["keyword"],"settings":{"foreground":"#782765"}},{"scope":["string"],"settings":{"foreground":"#27546a"}},{"scope":["comment"],"settings":{"foreground":"#50645c"}},{"scope":["entity.name.function"],"settings":{"foreground":"#924019"}},{"scope":["variable"],"settings":{"foreground":"#473d76"}},{"scope":["constant"],"settings":{"foreground":"#5b5426"}}]}],"useStarlightUiThemeColors":false,"defaultProps":{"frame":"terminal"},"styleOverrides":{"codeFontFamily":"var(--tfsl-font-code)","codeFontSize":"14px","codeLineHeight":"1.5","borderRadius":"8px","borderWidth":"1px","borderColor":["#2e354a","#cbd5e1"],"focusBorder":["#3b82f6","#2563eb"],"codeBackground":["#090a0d","#f1f5f9"],"codeForeground":["#f0f2f5","#0f172a"],"frames":{"editorBackground":["#090a0d","#f1f5f9"],"editorActiveTabBackground":["#090a0d","#f1f5f9"],"editorActiveTabForeground":["#f0f2f5","#0f172a"],"editorActiveTabBorderColor":["#2e354a","#cbd5e1"],"editorTabBarBackground":["#161922","#ffffff"],"editorTabBarBorderColor":["#2e354a","#cbd5e1"],"editorTabBarBorderBottomColor":["#2e354a","#cbd5e1"],"editorTabBorderRadius":"8px","terminalBackground":["#090a0d","#f1f5f9"],"terminalTitlebarBackground":["#161922","#ffffff"],"terminalTitlebarForeground":["#e1e4ea","#334155"],"terminalTitlebarBorderBottomColor":["#2e354a","#cbd5e1"],"inlineButtonForeground":["#e1e4ea","#334155"],"inlineButtonBorder":["#2e354a","#cbd5e1"],"inlineButtonBorderOpacity":"0.4","inlineButtonBackgroundIdleOpacity":"0","tooltipSuccessBackground":["#f97316","#ea580c"],"tooltipSuccessForeground":["#0c0d10","#ffffff"]},"textMarkers":{"markBackground":["#f97316","#f97316"],"markBorderColor":["#f97316","#f97316"],"insBackground":["#22c55e","#22c55e"],"insBorderColor":["#22c55e","#22c55e"],"insDiffIndicatorColor":["#22c55e","#22c55e"],"delBackground":["#ef4444","#ef4444"],"delBorderColor":["#ef4444","#ef4444"],"delDiffIndicatorColor":["#ef4444","#ef4444"]}}};
      const expressiveCode = mergeCodeConfig(ecDefaults, config?.expressiveCode);
      updateConfig({ customCss, components, expressiveCode });
    }
  } };
}

@layer tfsl.accent {
  :root,
  ::backdrop {
    --tfsl-color-accent-base: #f97316;
    --tfsl-color-accent-low: #431407;
    --tfsl-color-accent-high: #fdba74;
    --sl-color-accent: var(--tfsl-color-accent-base);
    --sl-color-accent-low: var(--tfsl-color-accent-low);
    --sl-color-accent-high: var(--tfsl-color-accent-high);
  }

  :root[data-theme='light'],
  [data-theme='light'] ::backdrop {
    --tfsl-color-accent-base: #ea580c;
    --tfsl-color-accent-low: #ffedd5;
    --tfsl-color-accent-high: #9a3412;
    --sl-color-accent: var(--tfsl-color-accent-base);
    --sl-color-accent-low: var(--tfsl-color-accent-low);
    --sl-color-accent-high: var(--tfsl-color-accent-high);
  }
}

@layer tfsl.base {
  body { font-family: var(--tfsl-font-body); font-size: 16px; line-height: 1.6; }
  header, nav, aside, button, select, input { font-family: var(--tfsl-font-ui); font-size: 14px; line-height: 1.5; }
  code, pre { font-family: var(--tfsl-font-code); font-size: 14px; line-height: 1.5; }
  nav { background-color: var(--tfsl-color-navigation); }
  .sl-markdown-content pre { background-color: var(--tfsl-color-code); }
  .sl-markdown-content blockquote { background-color: var(--tfsl-color-panel); border-color: var(--tfsl-color-border); }
  .sl-markdown-content details { background-color: var(--tfsl-color-raised); border-radius: var(--tfsl-radius-small); padding: var(--tfsl-space-small); }
  .sl-markdown-content small { color: var(--tfsl-color-muted); }
  @media (min-width: 50rem) { :root { --sl-content-width: min(1152px, 1152px); } }
  h1, .sl-markdown-content :is(h1, h2, h3, h4, h5, h6) {
    font-family: var(--tfsl-font-heading, var(--sl-font));
    line-height: var(--sl-line-height-headings, 1.2);
    color: var(--tfsl-color-secondary, var(--sl-color-white));
  }

  .sl-markdown-content h1 {
    font-size: var(--sl-text-h1);
  }

  .sl-markdown-content h2 {
    font-size: var(--sl-text-h2);
  }

  .sl-markdown-content h3 {
    font-size: var(--sl-text-h3);
  }

  .sl-markdown-content h4 {
    font-size: var(--sl-text-h4);
  }

  .sl-markdown-content h5 {
    font-size: var(--sl-text-h5);
  }

  .sl-markdown-content h6 {
    font-size: var(--sl-text-h6);
  }

  /* Responsive heading scaling across breakpoints */
  @media (min-width: 50rem) {
    .sl-markdown-content h1 {
      font-size: calc(var(--sl-text-h1) * 1.15);
    }
    .sl-markdown-content h2 {
      font-size: calc(var(--sl-text-h2) * 1.1);
    }
  }

  @media (min-width: 72rem) {
    .sl-markdown-content h1 {
      font-size: calc(var(--sl-text-h1) * 1.25);
    }
    .sl-markdown-content h2 {
      font-size: calc(var(--sl-text-h2) * 1.15);
    }
  }

  /* Card and surface styling */
  .card,
  .sl-markdown-content .card {
    background-color: var(--tfsl-color-card);
    border: var(--tfsl-border-width, 1px) var(--tfsl-border-style) var(--tfsl-color-border);
    border-radius: var(--tfsl-radius, 8px);
  }

  /* Selection styling */
  ::selection {
    background-color: var(--tfsl-color-selection-background);
    color: var(--tfsl-color-selection-text);
  }
}

/* Theme Forge Stellar Loom v2 - Expressive Code overrides */
@layer tfsl.overrides {
  .sl-markdown-content .expressive-code pre,
  .expressive-code pre {
    background-color: var(--code-background, var(--ec-codeBg));
  }
  .expressive-code pre, .expressive-code pre > code {
    font-family: var(--ec-codeFontFml);
    font-size: var(--ec-codeFontSize);
    line-height: var(--ec-codeLineHt);
  }
}

/* Theme Forge Stellar Loom v2 - Layer order declaration */
@layer starlight, tfsl;
@layer tfsl.tokens, tfsl.base, tfsl.accent, tfsl.overrides;

@layer tfsl.overrides {
  :focus-visible {
    outline: var(--tfsl-focus-width, 2px) solid var(--tfsl-color-focus);
    outline-offset: var(--tfsl-focus-offset);
  }

  .sl-markdown-content a:focus-visible {
    outline: var(--tfsl-focus-width, 2px) solid var(--tfsl-color-focus);
    outline-offset: var(--tfsl-focus-offset);
  }
  .tfsl-page-title-frame {
    border-left: 4px solid var(--sl-color-accent);
    padding-left: 1rem;
    margin-bottom: 1.5rem;
  }
}

@layer tfsl.tokens {
  :root,
  ::backdrop {
    --sl-font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --sl-font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --tfsl-font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --tfsl-font-heading: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --tfsl-font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --tfsl-font-code: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --sl-text-body: 16px;
    --sl-line-height: 1.6;
    --sl-line-height-headings: 1.25;
    --sl-text-h1: 28px;
    --sl-text-h2: 24px;
    --sl-text-h3: 20px;
    --sl-text-h4: 18px;
    --sl-text-h5: 16px;
    --sl-text-h6: 14px;
    --sl-content-width: 1152px;
    --sl-sidebar-width: 288px;
    --tfsl-spacing: 4px;
    --tfsl-space-small: 2px;
    --tfsl-space-large: 8px;
    --tfsl-space-section: 16px;
    --tfsl-radius-small: 4px;
    --tfsl-border-style: solid;
    --tfsl-focus-offset: 2px;
    --tfsl-radius: 8px;
    --tfsl-border-width: 1px;
    --tfsl-focus-width: 2px;

    /* Theme color roles */
    --tfsl-color-page: #0c0d10;
    --tfsl-color-navigation: #12141a;
    --tfsl-color-header: #12141a;
    --tfsl-color-sidebar: #0f1015;
    --tfsl-color-raised: #161922;
    --tfsl-color-panel: #1a1e29;
    --tfsl-color-card: #131620;
    --tfsl-color-inline-code: #1e2330;
    --tfsl-color-code: #090a0d;
    --tfsl-color-body: #f0f2f5;
    --tfsl-color-secondary: #e1e4ea;
    --tfsl-color-muted: #8a92a6;
    --tfsl-color-inverted: #0c0d10;
    --tfsl-color-link: #60a5fa;
    --tfsl-color-hairline: #232838;
    --tfsl-color-border: #2e354a;
    --tfsl-color-focus: #3b82f6;
    --tfsl-color-selection-background: #3b82f6;
    --tfsl-color-selection-text: #ffffff;

    /* Starlight standard token mappings */
    --sl-color-bg: var(--tfsl-color-page);
    --sl-color-bg-nav: var(--tfsl-color-header);
    --sl-color-bg-sidebar: var(--tfsl-color-sidebar);
    --sl-color-bg-inline-code: var(--tfsl-color-inline-code);
    --sl-color-text: var(--tfsl-color-body);
    --sl-color-text-accent: var(--tfsl-color-link);
    --sl-color-text-invert: var(--tfsl-color-inverted);
    --sl-color-hairline: var(--tfsl-color-hairline);
    --sl-color-hairline-light: var(--tfsl-color-border);
    --sl-color-hairline-shade: var(--tfsl-color-border);
    --sl-color-white: var(--tfsl-color-secondary);
    --sl-color-black: var(--tfsl-color-page);
  }

  :root[data-theme='light'],
  [data-theme='light'] ::backdrop {
    /* Theme color roles */
    --tfsl-color-page: #f8fafc;
    --tfsl-color-navigation: #ffffff;
    --tfsl-color-header: #ffffff;
    --tfsl-color-sidebar: #f1f5f9;
    --tfsl-color-raised: #ffffff;
    --tfsl-color-panel: #f8fafc;
    --tfsl-color-card: #ffffff;
    --tfsl-color-inline-code: #e2e8f0;
    --tfsl-color-code: #f1f5f9;
    --tfsl-color-body: #0f172a;
    --tfsl-color-secondary: #334155;
    --tfsl-color-muted: #64748b;
    --tfsl-color-inverted: #ffffff;
    --tfsl-color-link: #2563eb;
    --tfsl-color-hairline: #e2e8f0;
    --tfsl-color-border: #cbd5e1;
    --tfsl-color-focus: #2563eb;
    --tfsl-color-selection-background: #2563eb;
    --tfsl-color-selection-text: #ffffff;

    /* Starlight standard token mappings */
    --sl-color-bg: var(--tfsl-color-page);
    --sl-color-bg-nav: var(--tfsl-color-header);
    --sl-color-bg-sidebar: var(--tfsl-color-sidebar);
    --sl-color-bg-inline-code: var(--tfsl-color-inline-code);
    --sl-color-text: var(--tfsl-color-body);
    --sl-color-text-accent: var(--tfsl-color-link);
    --sl-color-text-invert: var(--tfsl-color-inverted);
    --sl-color-hairline: var(--tfsl-color-hairline);
    --sl-color-hairline-light: var(--tfsl-color-border);
    --sl-color-hairline-shade: var(--tfsl-color-border);
    --sl-color-white: var(--tfsl-color-secondary);
    --sl-color-black: var(--tfsl-color-page);
  }
}
